const results = await Promise.allSettled([
  tools.exec_command({cmd:"pwd && git rev-parse --show-toplevel && git status --short && git log -5 --oneline", workdir:"/tmp/bench/ws", max_output_tokens:2000}),
  tools.exec_command({cmd:"find /tmp/bench -maxdepth 2 -type d -name '*v0.3.0*' -print", workdir:"/tmp/bench/ws", max_output_tokens:1000}),
  tools.exec_command({cmd:"rg --files contracts/src contracts-proc/src lib/crypto/src | head -100", workdir:"/tmp/bench/ws", max_output_tokens:3000})
]);
for (const r of results) text(r.status === "fulfilled" ? r.value.output : String(r.reason));

const cmds = [
  ["source-tree-diff", "git diff --no-index --stat /tmp/bench/ws-v0.3.0/contracts/src /tmp/bench/ws/contracts/src", 2000],
  ["key-source-diff", "git diff --no-index --unified=3 /tmp/bench/ws-v0.3.0/contracts/src/token/erc20/mod.rs /tmp/bench/ws/contracts/src/token/erc20/mod.rs", 5000],
  ["erc721-diff", "git diff --no-index --unified=3 /tmp/bench/ws-v0.3.0/contracts/src/token/erc721/mod.rs /tmp/bench/ws/contracts/src/token/erc721/mod.rs", 5000],
  ["storage-syntax", "rg -n '#\\[storage\\]|pub struct .*Storage|struct .*Storage|StorageSlot|#[[:space:]]*storage' contracts/src", 4000]
];
const results = await Promise.allSettled(cmds.map(async ([name, cmd, max_output_tokens]) => ({name, ...(await tools.exec_command({cmd, workdir:"/tmp/bench/ws", max_output_tokens}))})));
for (const r of results) text(r.status === "fulfilled" ? `=== ${r.value.name} ===\n${r.value.output}` : String(r.reason));

