  ["storage-schemas", "python3 - <<'PY'
import pathlib,re
roots=[pathlib.Path('/tmp/bench/ws-v0.3.0/contracts/src'),pathlib.Path('/tmp/bench/ws/contracts/src')]
def decls(root):
 d={}
 for f in root.rglob('*.rs'):
  s=f.read_text()
  for m in re.finditer(r'#\[storage\]\s*(?:pub\s+)?struct\s+([A-Za-z0-9_]+)(?:<[^>{}]*>)?\s*\{',s):
   i=m.end(); depth=1; j=i
   while j<len(s) and depth:
    if s[j]=='{': depth+=1
    elif s[j]=='}': depth-=1
    j+=1
   body=s[i:j-1]
   fields=[]
   for line in body.splitlines():
    x=line.strip()
    if not x or x.startswith('///') or x.startswith('//') or x.startswith('#['): continue
    # include field declaration lines (storage structs use one line fields)
    if ':' in x and not x.startswith('where'):
     fields.append(re.sub(r'\s+',' ',x.rstrip(',')))
   key=f.relative_to(root).as_posix()+':'+m.group(1)
   d[key]=fields
 return d
a,b=map(decls,roots)
print('baseline storage structs',len(a),'current',len(b))
print('added',sorted(set(b)-set(a)))
print('removed',sorted(set(a)-set(b)))
changed=[]
for k in sorted(set(a)&set(b)):
 if a[k]!=b[k]: changed.append((k,a[k],b[k]))
print('changed',len(changed))
for row in changed: print(row)
