   if re.search(r'#\[cfg\(test\)\]',prefix): continue
   i=m.end(); depth=1; j=i
   while j<len(s) and depth:
    if s[j]=='{': depth+=1
    elif s[j]=='}': depth-=1
    j+=1
   body=s[i:j-1]
   fields=[]
   # Split fields by semicolon (sol_storage-like nested not used here) or line, keep visibility:name type
   for line in body.splitlines():
    x=line.strip()
