const result = await tools.exec_command({cmd:"python3 - <<'PY'
import pathlib,re
roots=[pathlib.Path('/tmp/bench/ws-v0.3.0/examples'),pathlib.Path('/tmp/bench/ws/examples')]
def blocks(root):
 out={}
 for f in root.rglob('src/**/*.rs'):
  if not f.is_file(): continue
  s=f.read_text()
  for m in re.finditer(r'#\[public\]\s*(?:#\[[^]]+\]\s*)*impl\s*([^{}]+)\{',s):
   h=re.sub(r'\s+',' ',m.group(1)).strip();i=m.end();d=1;j=i
   while j<len(s) and d:
    if s[j]=='{':d+=1
    elif s[j]=='}':d-=1
    j+=1
   body=s[i:j-1];pos=0;ms=[]
   while True:
    n=re.search(r'\bfn\s+(\w+)\s*\(',body[pos:])
    if not n:break
    start=pos+n.start();p=body.find('(',start);d=0;k=p
    while k<len(body):
     if body[k]=='(':d+=1
     elif body[k]==')':
      d-=1
      if d==0:break
     k+=1
    e=k+1;ang=br=0
    while e<len(body):
     c=body[e]
     if c=='<':ang+=1
     elif c=='>':ang=max(0,ang-1)
     elif c=='[':br+=1
     elif c==']':br=max(0,br-1)
     elif c=='{' and ang==0 and br==0:break
     e+=1
    sig=re.sub(r'\s+',' ',body[start:e].strip())
    selector=re.findall(r'#\[selector\(([^]]+)\)\]',body[max(0,start-150):start])
    ms.append(('selector='+','.join(selector)+' ' if selector else '')+sig)
    pos=e+1
   key=f.relative_to(root).as_posix()+':'+h;out[key]=ms
 return out
a,b=map(blocks,roots)
print('public impl blocks baseline/current',len(a),len(b))
print('added blocks',sorted(set(b)-set(a)))
print('removed blocks',sorted(set(a)-set(b)))
for k in sorted(set(a)&set(b)):
 if a[k]!=b[k]: print('\nDIFF',k,'\n old:',a[k],'\n new:',b[k])
PY", workdir:"/tmp/bench/ws", max_output_tokens:5000});
text(result.output);

