        Erc1967Utils::get_beacon(self)
    }
}

unsafe impl IProxy for BeaconProxy {
    fn implementation(&self) -> Result<Address, Vec<u8>> {
        Ok(IBeaconInterface::new(self.get_beacon())
            .implementation(self.vm(), Call::new())?)
    }
