    /// * [`Error::EmptyCode`] - If the target contract has no code.
    pub fn function_delegate_call<T: TopLevelStorage + HostAccess>(
        context: &mut T,
        target: Address,
        data: &[u8],
    ) -> Result<Vec<u8>, Error> {
        let call = Call::new_mutating(context);
