            .log(erc1967::Upgraded { implementation: new_implementation });

        if data.is_empty() {
            Erc1967Utils::check_non_payable(context)?;
        } else {
            AddressUtils::function_delegate_call(
                context,
                new_implementation,
                data.as_ref(),
