//! Shared helpers for integration tests that run against the Stylus SDK devnet.

mod account;
mod cache;
mod deploy;
mod error;
mod event;
mod receipt;

pub use account::{Account, Wallet};
pub use cache::cache_contract;
pub use deploy::{
    deploy_package, deploy_package_with_features, deploy_wasm_file,
    AbiTypeToString, Constructor, ContractInitializationError,
};
pub use error::{Panic, PanicCode, Revert};
pub use event::EventExt;
pub use receipt::Receipt;
pub use stylus_tools::devnet::addresses::STYLUS_DEPLOYER;

/// Sends a generated Alloy contract call.
#[macro_export]
macro_rules! send {
    ($call:expr) => {
        $call.send().await
    };
}

/// Sends a generated Alloy contract call and waits for its receipt.
#[macro_export]
macro_rules! watch {
    ($call:expr) => {
        $crate::send!($call)?.watch().await
    };
}

/// Sends a generated Alloy contract call and returns its mined receipt.
#[macro_export]
macro_rules! receipt {
    ($call:expr) => {
        $crate::send!($call)?.get_receipt().await
    };
}
# This workflow runs our end-to-end tests suite.
#
# The SDK integration-test tooling manages a Nitro devnet in Docker. Each integration-test binary
# shares its node across tests and creates funded accounts as needed.
name: e2e
permissions:
  contents: read
on:
  push:
    branches: [main, v*]
  pull_request:
concurrency:
  group: ${{ github.workflow }}-${{ github.head_ref || github.run_id }}
  cancel-in-progress: true
env:
  CARGO_TERM_COLOR: always
jobs:
  required:
    name: tests
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4

      - name: Install rust
        uses: actions-rust-lang/setup-rust-toolchain@v1
        with:
          toolchain: 1.91.0
          cache-key: "e2e-tests"
          rustflags: ""

      - name: Install wasm-opt
        run: cargo install wasm-opt@0.116.1

      - name: run integration tests
        run: ./scripts/e2e-tests.sh
name: check-wasm
# This workflow checks that the compiled wasm binary of every example contract
# can be deployed to Arbitrum Stylus.
permissions:
  contents: read
on:
  push:
    branches: [main, v*]
